import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_database/firebase_database.dart';
import 'firebase_options.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await Firebase.initializeApp(options:DefaultFirebaseOptions.currentPlatform);runApp(const EventsApp());}
class EventsApp extends StatelessWidget{const EventsApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Campus Events Live',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:Colors.deepPurple),useMaterial3:true),home:const EventsPage());}
class EventsPage extends StatefulWidget{const EventsPage({super.key});@override State<EventsPage> createState()=>_EventsPageState();}
class _EventsPageState extends State<EventsPage>{final ref=FirebaseDatabase.instance.ref('campus_events');final title=TextEditingController();final venue=TextEditingController();Future<void> publish()async{if(title.text.trim().isEmpty)return;await ref.push().set({'title':title.text.trim(),'venue':venue.text.trim(),'createdAt':DateTime.now().toIso8601String()});title.clear();venue.clear();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Event published')));}
@override void dispose(){title.dispose();venue.dispose();super.dispose();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Campus Pulse • Live Events')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Event name',border:OutlineInputBorder())),const SizedBox(height:8),TextField(controller:venue,decoration:const InputDecoration(labelText:'Venue',border:OutlineInputBorder())),const SizedBox(height:8),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:publish,icon:const Icon(Icons.campaign),label:const Text('Publish event'))),const SizedBox(height:20),const Align(alignment:Alignment.centerLeft,child:Text('Live campus feed',style:TextStyle(fontWeight:FontWeight.bold,fontSize:20))),Expanded(child:StreamBuilder<DatabaseEvent>(stream:ref.onValue,builder:(c,s){if(s.hasError)return Center(child:Text('Connection issue: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final raw=s.data!.snapshot.value;if(raw==null)return const Center(child:Text('No events published'));final map=Map<dynamic,dynamic>.from(raw as Map);final events=map.entries.toList().reversed.toList();return ListView(children:events.map((e){final item=Map<dynamic,dynamic>.from(e.value);return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.event_available)),title:Text('${item['title']}'),subtitle:Text('📍 ${item['venue']}'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>ref.child('${e.key}').remove())));}).toList());}))])));}
